422 | 
423 | /* ── Stock row (compact table-style card) ── */
424 | .card {
425 |   display: grid;
426 |   grid-template-columns:
427 |     var(--c-rank) var(--c-spark) var(--c-ticker) var(--c-price)
428 |     var(--c-chg) var(--c-score) var(--c-pe) var(--c-rsi)
429 |     var(--c-eps) var(--c-margin) var(--c-cap);
430 |   align-items: center;
431 |   padding: 0 10px;
432 |   height: 44px;
433 |   background: var(--bg2);
434 |   border: 1px solid var(--border);
435 |   border-radius: var(--radius);
436 |   cursor: pointer;
437 |   transition: background .18s, border-color .18s, transform .18s cubic-bezier(0.34,1.56,0.64,1), box-shadow .18s;
438 |   will-change: transform;
439 | }
440 | .card:hover {
441 |   background: var(--bg3);
442 |   border-color: var(--accent);
443 |   transform: translateX(4px) scale(1.012);
444 |   box-shadow: -3px 0 0 0 var(--accent), 0 6px 24px rgba(88,166,255,0.13);
445 |   z-index: 1;
446 |   position: relative;
447 | }
448 | 
449 | /* rank */
450 | .row-rank { text-align: center; font-size: .75rem; color: var(--muted); font-weight: 600; transition: transform .2s cubic-bezier(0.34,1.56,0.64,1); }
451 | .row-rank.top3 { color: var(--gold); font-weight: 700; }
452 | .card:hover .row-rank { transform: scale(1.35); }
453 | 
454 | /* sparkline cell */
455 | .row-spark { width: var(--c-spark); height: 36px; display: flex; align-items: center; padding: 0 4px; transition: filter .2s, transform .2s; }
456 | .row-spark canvas { display: block; width: 100%; height: 36px; transition: filter .2s; }
457 | .card:hover .row-spark { transform: scaleY(1.12); }
458 | .card:hover .row-spark canvas { filter: brightness(1.35) drop-shadow(0 0 4px rgba(88,166,255,0.5)); }
459 | 
460 | /* ticker + name stacked */
461 | .row-ticker { display: flex; flex-direction: column; gap: 1px; overflow: hidden; padding-right: 6px; }
462 | .row-ticker-sym  { font-size: .85rem; font-weight: 700; white-space: nowrap; transition: color .15s, letter-spacing .15s; }
463 | .row-ticker-name { font-size: .68rem; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; transition: color .15s; }
464 | .card:hover .row-ticker-sym  { color: var(--accent); letter-spacing: .03em; }
465 | .card:hover .row-ticker-name { color: var(--text); }
466 | 
467 | /* right-aligned cells */
468 | .row-price  { text-align: right; font-size: .82rem; font-weight: 600; padding-right: 6px; transition: transform .15s; }
469 | .row-chg    { text-align: right; padding-right: 6px; }
470 | .row-score  { text-align: right; font-size: .85rem; font-weight: 800; padding-right: 6px; transition: transform .2s cubic-bezier(0.34,1.56,0.64,1); }
471 | .row-pe, .row-rsi, .row-eps, .row-margin, .row-cap { text-align: right; font-size: .78rem; color: var(--muted); padding-right: 6px; transition: color .15s; }
472 | .card:hover .row-price  { transform: scale(1.06); }
473 | .card:hover .row-score  { transform: scale(1.18); }
474 | .card:hover .row-pe, .card:hover .row-rsi,
475 | .card:hover .row-eps, .card:hover .row-margin,
476 | .card:hover .row-cap    { color: var(--text); }
477 | 
478 | /* change text (no pill background — just color) */
479 | .chg { font-size: .78rem; font-weight: 600; }
480 | .chg.pos { color: var(--green); }
481 | .chg.neg { color: var(--red); }
482 | .chg.neu { color: var(--muted); }
483 | 
484 | /* score colour */
485 | .score-val.high   { color: var(--green); }
486 | .score-val.medium { color: var(--gold); }
487 | .score-val.low    { color: var(--red); }
488 | 
489 | /* Subscore weight tag in modal */
490 | .subscore-weight {
491 |   margin-left: 5px;
492 |   font-size: .68rem;
493 |   color: var(--accent);
494 |   opacity: .8;
495 | }
