   1 | /* ── StockPicker AI — frontend logic ─────────────────────────────────────── */
   2 | 
   3 | const API = 'http://127.0.0.1:5000/api';
   4 | let stockData   = [];
   5 | let activeWeights = {};  // weights used for the current render
   6 | 
   7 | const SIGNAL_LABELS = {
   8 |   momentum:  'Momentum',
   9 |   ma:        'MA Signal',
  10 |   pe:        'Valuation',
  11 |   eps:       'EPS Growth',
  12 |   debt:      'Debt/Eq',
  13 |   margin:    'Margin',
  14 |   rsi_score: 'RSI',
  15 |   short:     'Short Interest',
  16 | };
  17 | 
  18 | // ── localStorage keys ─────────────────────────────────────────────────────
  19 | const LS_THEME     = 'sp_theme';
  20 | const LS_SCORES    = 'sp_score_history';   // { TICKER: [{ts, score}, ...] }
  21 | const LS_PORTFOLIO = 'sp_portfolio';        // { TICKER: sharesCount }
  22 | const LS_ALERTS    = 'sp_alerts';           // { TICKER: {price, score} }
  23 | 
  24 | // ── Theme ─────────────────────────────────────────────────────────────────
  25 | function toggleTheme() {
  26 |   const isLight = document.body.classList.toggle('light');
  27 |   document.getElementById('theme-toggle').textContent = isLight ? '☀' : '☾';
  28 |   localStorage.setItem(LS_THEME, isLight ? 'light' : 'dark');
  29 | }
  30 | 
  31 | function applyStoredTheme() {
  32 |   if (localStorage.getItem(LS_THEME) === 'light') {
  33 |     document.body.classList.add('light');
  34 |     document.getElementById('theme-toggle').textContent = '☀';
  35 |   }
  36 | }
  37 | 
  38 | // ── Boot ──────────────────────────────────────────────────────────────────
  39 | window.addEventListener('DOMContentLoaded', async () => {
  40 |   applyStoredTheme();
  41 |   await loadSectors();
  42 |   await loadStocks();
  43 | });
  44 | 
  45 | // ── Sector dropdown ───────────────────────────────────────────────────────
  46 | async function loadSectors() {
  47 |   try {
  48 |     const res  = await fetch(`${API}/sectors`);
  49 |     const data = await res.json();
  50 |     const sel  = document.getElementById('sector-select');
  51 |     sel.innerHTML = '';
  52 |     data.sectors.forEach(s => {
  53 |       const opt = document.createElement('option');
  54 |       opt.value = s;
  55 |       opt.textContent = s === 'all' ? 'All Sectors' : s;
  56 |       sel.appendChild(opt);
  57 |     });
  58 |   } catch { /* keep default */ }
  59 | }
  60 | 
  61 | // ── Main data loader ──────────────────────────────────────────────────────
  62 | async function loadStocks() {
  63 |   const sector = document.getElementById('sector-select').value;
  64 |   const mode   = document.getElementById('mode-select').value;
  65 |   const url    = `${API}/top-stocks?sector=${encodeURIComponent(sector)}&mode=${mode}`;
  66 | 
  67 |   showLoading(true);
  68 |   hideBanner();
  69 |   setRefreshSpinning(true);
  70 | 
  71 |   try {
  72 |     const res  = await fetch(url);
  73 |     if (!res.ok) throw new Error(`HTTP ${res.status}`);
  74 |     const data = await res.json();
  75 |     stockData     = data.stocks || [];
  76 |     activeWeights = data.weights || {};
  77 | 
  78 |     const ts = data.generated
  79 |       ? 'Updated ' + new Date(data.generated).toLocaleTimeString()
  80 |       : '';
  81 |     document.getElementById('last-updated').textContent = ts;
  82 | 
  83 |     // Feature 5: persist score history for every fetched ticker
  84 |     persistScoreHistory(stockData);
  85 | 
  86 |     renderWeightBar(activeWeights, data.mode);
  87 |     reRender();
  88 | 
  89 |     // Feature 6: check alerts after data loads
  90 |     checkAlerts(stockData);
  91 | 
  92 |     // Feature 4: refresh portfolio panel if open
  93 |     if (!document.getElementById('portfolio-panel').classList.contains('hidden')) {
  94 |       renderPortfolioPanel();
  95 |     }
  96 |   } catch (err) {
  97 |     showBanner(`⚠️ Could not reach the backend: ${err.message}. Is the Flask server running?`, 'error');
  98 |   } finally {
  99 |     showLoading(false);
 100 |     setRefreshSpinning(false);
 101 |   }
 102 | }
