 370 | /** Save the current score for each ticker with a UTC timestamp. */
 371 | function persistScoreHistory(stocks) {
 372 |   let history = {};
 373 |   try { history = JSON.parse(localStorage.getItem(LS_SCORES) || '{}'); } catch {}
 374 |   const ts = Date.now();
 375 |   stocks.forEach(s => {
 376 |     if (!history[s.ticker]) history[s.ticker] = [];
 377 |     // Only append if the last entry was > 5 minutes ago (avoid duplicates on rapid refresh)
 378 |     const last = history[s.ticker].at(-1);
 379 |     if (!last || ts - last.ts > 5 * 60 * 1000) {
 380 |       history[s.ticker].push({ ts, score: s.score });
 381 |     }
 382 |     // Keep only the last 60 data points per ticker
 383 |     if (history[s.ticker].length > 60) history[s.ticker] = history[s.ticker].slice(-60);
 384 |   });
 385 |   try { localStorage.setItem(LS_SCORES, JSON.stringify(history)); } catch {}
 386 | }
 387 | 
 388 | /** Draw a compact line chart of score-over-time onto #score-history-canvas. */
 389 | function drawScoreHistoryChart(ticker) {
 390 |   let history = {};
 391 |   try { history = JSON.parse(localStorage.getItem(LS_SCORES) || '{}'); } catch {}
 392 |   const points = history[ticker] || [];
 393 | 
 394 |   const canvas  = document.getElementById('score-history-canvas');
 395 |   const emptyEl = document.getElementById('score-history-empty');
 396 |   if (!canvas) return;
 397 | 
 398 |   if (points.length < 2) {
 399 |     canvas.style.display = 'none';
 400 |     emptyEl && emptyEl.classList.remove('hidden');
 401 |     return;
 402 |   }
 403 |   emptyEl && emptyEl.classList.add('hidden');
 404 |   canvas.style.display = 'block';
 405 | 
 406 |   const dpr = window.devicePixelRatio || 1;
 407 |   const W   = canvas.parentElement.clientWidth || 400;
 408 |   const H   = 80;
 409 |   canvas.width  = W * dpr;
 410 |   canvas.height = H * dpr;
 411 |   canvas.style.width  = W + 'px';
 412 |   canvas.style.height = H + 'px';
 413 | 
 414 |   const ctx = canvas.getContext('2d');
 415 |   ctx.scale(dpr, dpr);
 416 | 
 417 |   const scores = points.map(p => p.score);
 418 |   const minS   = Math.min(...scores);
 419 |   const maxS   = Math.max(...scores);
 420 |   const range  = Math.max(maxS - minS, 5);
 421 |   const pad    = { t: 6, b: 18, l: 6, r: 6 };
 422 |   const iW     = W - pad.l - pad.r;
 423 |   const iH     = H - pad.t - pad.b;
 424 | 
 425 |   const xFn = i => pad.l + (i / (points.length - 1)) * iW;
 426 |   const yFn = v => pad.t + iH - ((v - minS) / range) * iH;
 427 | 
 428 |   ctx.fillStyle = '#21262d';
 429 |   ctx.fillRect(0, 0, W, H);
 430 | 
 431 |   const grad = ctx.createLinearGradient(0, pad.t, 0, pad.t + iH);
 432 |   grad.addColorStop(0, 'rgba(88,166,255,0.35)');
 433 |   grad.addColorStop(1, 'rgba(88,166,255,0.02)');
 434 |   ctx.beginPath();
 435 |   ctx.moveTo(xFn(0), yFn(scores[0]));
 436 |   scores.forEach((v, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(v)); });
 437 |   ctx.lineTo(xFn(scores.length - 1), pad.t + iH);
 438 |   ctx.lineTo(xFn(0), pad.t + iH);
 439 |   ctx.closePath();
 440 |   ctx.fillStyle = grad;
 441 |   ctx.fill();
 442 | 
 443 |   ctx.beginPath();
 444 |   ctx.moveTo(xFn(0), yFn(scores[0]));
 445 |   scores.forEach((v, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(v)); });
 446 |   ctx.strokeStyle = '#58a6ff';
 447 |   ctx.lineWidth   = 2;
 448 |   ctx.lineJoin    = 'round';
 449 |   ctx.stroke();
 450 | 
 451 |   const special = new Set([0, scores.length - 1,
 452 |     scores.indexOf(Math.min(...scores)), scores.indexOf(Math.max(...scores))]);
 453 |   ctx.textAlign = 'center';
 454 |   special.forEach(i => {
 455 |     const x = xFn(i), y = yFn(scores[i]);
 456 |     ctx.beginPath();
 457 |     ctx.arc(x, y, 2.5, 0, Math.PI * 2);
 458 |     ctx.fillStyle = '#58a6ff';
 459 |     ctx.fill();
 460 |     const labelY = y < pad.t + 12 ? y + 12 : y - 5;
 461 |     ctx.fillStyle = '#8b949e';
 462 |     ctx.font = '9px sans-serif';
 463 |     ctx.fillText(scores[i], x, labelY);
 464 |   });
 465 | 
 466 |   ctx.fillStyle = '#8b949e';
 467 |   ctx.font = '9px sans-serif';
 468 |   ctx.textAlign = 'left';
 469 |   ctx.fillText(fmtDate(points[0].ts), pad.l, H - 4);
 470 |   ctx.textAlign = 'right';
 471 |   ctx.fillText(fmtDate(points.at(-1).ts), W - pad.r, H - 4);
 472 | }
 473 | 
 474 | function fmtDate(ts) {
 475 |   const d = new Date(ts);
 476 |   return `${d.getMonth()+1}/${d.getDate()} ${d.getHours()}:${String(d.getMinutes()).padStart(2,'0')}`;
 477 | }
