107 |   const pills = document.getElementById('weight-pills');
108 |   if (!weights || !Object.keys(weights).length) {
109 |     bar.classList.add('hidden');
110 |     return;
111 |   }
112 | 
113 |   const modeTag  = mode ? ` <span style="color:var(--accent);font-weight:700;">[${mode}]</span>` : '';
114 |   const maxW     = Math.max(...Object.values(weights));
115 | 
116 |   pills.innerHTML = Object.entries(weights).map(([key, val]) => {
117 |     const pct   = Math.round(val * 100);
118 |     const barW  = Math.round((val / maxW) * 100);
119 |     const label = SIGNAL_LABELS[key] || key;
120 |     return `<span class="weight-pill">
121 |       <span class="weight-pill-name">${label}</span>
122 |       <span class="weight-pill-track"><span class="weight-pill-fill" style="width:${barW}%"></span></span>
123 |       <span class="weight-pill-val">${pct}%</span>
124 |     </span>`;
125 |   }).join('');
126 | 
127 |   document.querySelector('.weight-bar-label').innerHTML = `🎲 Formula${modeTag}:`;
128 |   bar.classList.remove('hidden');
129 | }
