const FALLBACK_TICKERS = [
  'AAPL','MSFT','GOOGL','AMZN','META','NVDA','TSLA','JPM','V','UNH',
  'HD','PG','MA','XOM','BAC','PFE','DIS','NFLX','ADBE','CRM',
  'INTC','AMD','QCOM','PYPL','SBUX','NKE','MCD','KO','PEP','WMT'
];

const RANDOM_BTN_THRESHOLD = 5;
let _randomBtnClicks = 0;

// Place the floating button at a random spot, keeping it fully on-screen.
function teleportRandomBtn() {
  const btn = document.getElementById('random-ticker-btn');
  if (!btn) return;
  const bw = btn.offsetWidth  || 90;
  const bh = btn.offsetHeight || 26;
  const maxX = window.innerWidth  - bw  - 16;
  const maxY = window.innerHeight - bh  - 16;
  const x = Math.max(8, Math.floor(Math.random() * maxX));
  const y = Math.max(8, Math.floor(Math.random() * maxY));
  btn.style.left = x + 'px';
  btn.style.top  = y + 'px';
}

// Update button label to reflect how many clicks remain.
function updateRandomBtnLabel() {
  const btn = document.getElementById('random-ticker-btn');
  if (!btn) return;
  const remaining = RANDOM_BTN_THRESHOLD - _randomBtnClicks;
  if (remaining <= 0) {
    btn.textContent = '🎲 Random';
  } else {
    btn.textContent = `🎲 ${remaining} more…`;
  }
}

function randomTicker() {
  _randomBtnClicks++;
  teleportRandomBtn();

  if (_randomBtnClicks < RANDOM_BTN_THRESHOLD) {
    // Not yet — tease the user and escape
    updateRandomBtnLabel();
    return;
  }

  // 5th click — actually fire and reset
  _randomBtnClicks = 0;
  updateRandomBtnLabel();

  const pool = stockData.length > 0
    ? stockData.map(s => s.ticker)
    : FALLBACK_TICKERS;
  const ticker = pool[Math.floor(Math.random() * pool.length)]
  const input  = document.getElementById('custom-ticker-input');
  input.value  = ticker;
  lookupCustomTicker();
}

// Set initial position once the DOM is ready
document.addEventListener('DOMContentLoaded', () => {
  teleportRandomBtn();
  updateRandomBtnLabel();
});

